if remaining[first] >= 3:
    remaining[first] -= 3
    visit(pair, sets + ((first, first, first),))
    remaining[first] += 3
if first < 27 and first % 9 <= 6 and remaining[first + 1] and remaining[first + 2]:
    for kind in (first, first + 1, first + 2):
        remaining[kind] -= 1
    visit(pair, sets + ((first, first + 1, first + 2),))
    for kind in (first, first + 1, first + 2):
        remaining[kind] += 1
